<script>let colorIndex={{ count($existingColors) }};document.getElementById('addColor').addEventListener('click',()=>{document.getElementById('colorRows').insertAdjacentHTML('beforeend',`<div class="color-admin-row"><input name="colors[${colorIndex}][nama_warna]" placeholder="Nama warna"><input type="color" name="colors[${colorIndex}][kode_warna]" value="#888888"><input type="number" min="0" name="colors[${colorIndex}][stok]" value="1" placeholder="Stok"><label class="check-inline"><input type="checkbox" name="colors[${colorIndex}][tersedia]" value="1" checked> Tersedia</label><button type="button" class="remove-color"><i class="fa-solid fa-trash"></i></button></div>`);colorIndex++});document.addEventListener('click',e=>{if(e.target.closest('.remove-color'))e.target.closest('.color-admin-row').remove()});</script>
